static int number(CFDictionaryRef p,CFStringRef k){CFNumberRef n=CFDictionaryGetValue(p,k);int v=-1;if(n&&CFGetTypeID(n)==CFNumberGetTypeID())CFNumberGetValue(n,kCFNumberIntType,&v);return v;}
int main(void){io_iterator_t it=0;IOReturn r=IOServiceGetMatchingServices(kIOMainPortDefault,IOServiceMatching("IOUSBHostDevice"),&it);if(r)return 2;io_service_t service;while((service=IOIteratorNext(it))){CFMutableDictionaryRef p=0;if(!IORegistryEntryCreateCFProperties(service,&p,0,0)){int vendor=number(p,CFSTR("idVendor")),product=number(p,CFSTR("idProduct")),cls=number(p,CFSTR("bDeviceClass"));if((vendor==0x0bda&&product==0x8922)||cls==9){printf("DEVICE=%04x:%04x class=%d\n",vendor,product,cls);IOCFPlugInInterface **plugin=0;SInt32 score=0;r=IOCreatePlugInInterfaceForService(service,kIOUSBDeviceUserClientTypeID,kIOCFPlugInInterfaceID,&plugin,&score);printf("CREATE_PLUGIN=0x%08x present=%d\n",r,plugin!=0);if(!r&&plugin){IOUSBDeviceInterface942 **device=0;HRESULT h=(*plugin)->QueryInterface(plugin,CFUUIDGetUUIDBytes(kIOUSBDeviceInterfaceID942),(LPVOID*)&device);printf("QUERY_942=0x%08x present=%d\n",(unsigned)h,device!=0);if(!h&&device){UInt32 location=0;UInt16 vid=0,pid=0;r=(*device)->GetLocationID(device,&location);printf("GET_LOCATION=0x%08x value=%08x\n",r,location);r=(*device)->GetDeviceVendor(device,&vid);printf("GET_VENDOR=0x%08x value=%04x\n",r,vid);r=(*device)->GetDeviceProduct(device,&pid);printf("GET_PRODUCT=0x%08x value=%04x\n",r,pid);(*device)->Release(device);}IODestroyPlugInInterface(plugin);}}CFRelease(p);}IOObjectRelease(service);}IOObjectRelease(it);return 0;}
